mapper.select:
select laar.id, laar.name, laar.activity_award_id, laar.activity_id, laar.type, laar.config_val, laar.status, laar.create_user_id, laar.update_user_id, laar.create_time, laar.update_time, laar.award_type, latity.name as activityName, awards.name as awardName, awards.equity_name as equityName, awards.detail_type as detailType from la_activity_award_rule laar join la_activity_award awards on laar.activity_award_id = awards.id left join la_activity latity on laar.activity_id = latity.id
and laar.is_delete = 0
and laar.name like concat('%',#{param.name},'%')
and laar.activity_award_id = #{param.activityAwardId}
and laar.activity_id = #{param.activityId}
and laar.type = #{param.type}
and laar.award_type = #{param.awardType}
and laar.config_val like concat('%',#{param.configVal},'%')
and laar.status = #{param.status}
and laar.create_user_id = #{param.createUserId}
and laar.update_user_id = #{param.updateUserId}
order by laar.id desc
